  if (support.has16m) {
    return 'truecolor (16m)';
  }

  if (support.has256) {
    return '256 colors';
  }

  if (support.hasBasic) {
    return 'basic (16 colors)';
  }

  return 'none';
}

import { colorEnabled } from './color-support.js';

const codes = {
  reset: [0, 0],
  bold: [1, 22],
  dim: [2, 22],
  red: [31, 39],
  green: [32, 39],
  yellow: [33, 39],
  blue: [34, 39],
  magenta: [35, 39],
  cyan: [36, 39],
};

function wrap(open, close, text) {
  return colorEnabled ? `\u001B[${open}m${text}\u001B[${close}m` : `${text}`;
}

export const { bold, dim, red, green, yellow, blue, magenta, cyan } =
  Object.fromEntries(
    Object.entries(codes).map(([name, [open, close]]) => [
      name,
      (text) => wrap(open, close, text),
    ]),
  );

#!/usr/bin/env node
import { colorSupport, colorEnabled, describeColorSupport } from '../src/color-support.js';
import { bold, dim, red, green, yellow, blue, cyan } from '../src/colors.js';

const level = colorEnabled ? colorSupport.level : 0;
const name = describeColorSupport();

console.log(`${bold(cyan('colorful-cli'))} — terminal color support`);
console.log(`  detection: ${green(name)} (level ${level})`);

if (colorEnabled) {
  console.log(
    `  ${red('red')} ${green('green')} ${yellow('yellow')} ${blue('blue')} ${cyan('cyan')} ${bold('bold')} ${dim('dim')}`,
  );
} else {
  console.log(
    dim('  Colors are disabled (piped output, NO_COLOR, or an unsupported terminal).'),
  );
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { describeColorSupport } from '../src/color-support.js';

test('describeColorSupport reports none when unsupported', () => {
  assert.equal(describeColorSupport(false), 'none');
  assert.equal(describeColorSupport(undefined), 'none');
});

test('describeColorSupport reports basic colors', () => {
  assert.equal(
    describeColorSupport({ hasBasic: true, has256: false, has16m: false }),
    'basic (16 colors)',
  );
});

test('describeColorSupport reports 256 colors', () => {
  assert.equal(
    describeColorSupport({ hasBasic: true, has256: true, has16m: false }),
    '256 colors',
  );
});

test('describeColorSupport reports truecolor', () => {
  assert.equal(
    describeColorSupport({ hasBasic: true, has256: true, has16m: true }),
    'truecolor (16m)',
  );
});

