import process from 'node:process';
import supportsColor from 'supports-color';

const EXPLICIT_COLOR_FLAG =
  /^--(?:color|colors)(?:=(?:true|false|always|never|16m|256|full|truecolor))?$|^--no-colou?rs?$/;
const NO_COLOR_FLAG = /^--no-colou?rs?$/;

function hasExplicitColorFlag(argv) {
  return argv.some((arg) => EXPLICIT_COLOR_FLAG.test(arg));
}

function hasNoColorFlag(argv) {
  return argv.some((arg) => NO_COLOR_FLAG.test(arg));
}

// `supports-color` accounts for TTY detection, TERM/COLORTERM capabilities,
// `--color`/`--no-color` flags, FORCE_COLOR and CI environments. It does not
// honor NO_COLOR, so the CLI resolves that here.
export function resolveColorSupport({ detected, env = {}, argv = [] }) {
  // An explicit CLI flag or FORCE_COLOR always wins over NO_COLOR.
  if ('FORCE_COLOR' in env || hasExplicitColorFlag(argv)) {
    return detected;
  }

  // Honor the NO_COLOR standard (https://no-color.org).
  if ('NO_COLOR' in env && env.NO_COLOR !== '') {
    return false;
  }

  return detected;
}

export const colorSupport = resolveColorSupport({
  detected: supportsColor.stdout ?? false,
  env: process.env,
  argv: process.argv,
});

export const colorEnabled = Boolean(colorSupport);

export function describeColorSupport(support = colorSupport) {
  if (!support) {
    return 'none';
  }

  if (support.has16m) {
    return 'truecolor (16m)';
  }

  if (support.has256) {
    return '256 colors';
  }

  if (support.hasBasic) {
    return 'basic (16 colors)';
  }

  return 'none';
}

export { hasNoColorFlag };

import test from 'node:test';
import assert from 'node:assert/strict';
import { resolveColorSupport, describeColorSupport } from '../src/color-support.js';

const truecolor = { level: 3, hasBasic: true, has256: true, has16m: true };
const detected = truecolor;

test('describeColorSupport reports none when unsupported', () => {
  assert.equal(describeColorSupport(false), 'none');
  assert.equal(describeColorSupport(undefined), 'none');
});

test('describeColorSupport reports basic colors', () => {
  assert.equal(
    describeColorSupport({ hasBasic: true, has256: false, has16m: false }),
    'basic (16 colors)',
  );
});

test('describeColorSupport reports 256 colors', () => {
  assert.equal(
    describeColorSupport({ hasBasic: true, has256: true, has16m: false }),
    '256 colors',
  );
});

test('describeColorSupport reports truecolor', () => {
  assert.equal(describeColorSupport(truecolor), 'truecolor (16m)');
});

test('keeps detected support when there are no overrides', () => {
  assert.equal(resolveColorSupport({ detected }), detected);
});

test('NO_COLOR with a value disables color', () => {
  assert.equal(resolveColorSupport({ detected, env: { NO_COLOR: '1' } }), false);
});

test('an empty NO_COLOR does not disable color', () => {
  assert.equal(resolveColorSupport({ detected, env: { NO_COLOR: '' } }), detected);
});

test('FORCE_COLOR overrides NO_COLOR', () => {
  assert.equal(
    resolveColorSupport({ detected, env: { NO_COLOR: '1', FORCE_COLOR: '3' } }),
    detected,
  );
});

test('an explicit --color flag overrides NO_COLOR', () => {
  assert.equal(
    resolveColorSupport({ detected, env: { NO_COLOR: '1' }, argv: ['node', 'cli', '--color'] }),
    detected,
  );
});

